import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 9 Flying cats","description":"学习 比较级与比较对象一致，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 9 Flying cats","description":"学习 比较级与比较对象一致，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 比较级与比较对象一致，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 8 A famous monastery","link":"/life/english/new-concept/book-3/unit-01/lesson-008"},"next":{"text":"第三册：培养技能 · Lesson 10 The loss of the Titanic","link":"/life/english/new-concept/book-3/unit-01/lesson-010"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 8 A famous monastery","link":"/life/english/new-concept/book-3/unit-01/lesson-008"},"next":{"text":"第三册：培养技能 · Lesson 10 The loss of the Titanic","link":"/life/english/new-concept/book-3/unit-01/lesson-010"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-009.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-009.md"}'),s={name:"life/english/new-concept/book-3/unit-01/lesson-009.md"};function i(l,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-9-flying-cats" tabindex="-1">第三册：培养技能 · Lesson 9 Flying cats <a class="header-anchor" href="#第三册-培养技能-·-lesson-9-flying-cats" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 9 Flying cats&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以动物运动和观察结果为主题，练习表达比较、范围和一般倾向。讨论能力时不能把一次观察直接推成所有个体的规律。学习使用比较级说明两种情形的差别，并通过 than 后省略的内容还原完整比较对象，避免表面流利但逻辑不一致。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>balance</td><td>/ˈbæləns/</td><td>n.</td><td>平衡</td><td>keep balance</td></tr><tr><td>flexible</td><td>/ˈfleksəbl/</td><td>adj.</td><td>灵活的</td><td>a flexible body</td></tr><tr><td>surface</td><td>/ˈsɜːfɪs/</td><td>n.</td><td>表面</td><td>a smooth surface</td></tr><tr><td>observe</td><td>/əbˈzɜːv/</td><td>v.</td><td>观察</td><td>observe movement</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>land on — 落在某个表面上</li><li>compared with — 与某对象比较时</li></ul><h2 id="语法讲解-比较级与比较对象一致" tabindex="-1">语法讲解：比较级与比较对象一致 <a class="header-anchor" href="#语法讲解-比较级与比较对象一致" aria-label="Permalink to &quot;语法讲解：比较级与比较对象一致&quot;">​</a></h2><p>比较级常由形容词加 er 或由 more 加多音节形容词构成，再用 than 引出比较对象。两边应比较同类事物，例如一只动物的速度与另一只动物的速度，而非速度与动物本身。much、far、slightly 可以修饰比较级，very 通常不能直接修饰比较级。the more ... the more ... 表示相关变化，不自动证明因果。使用一般现在时陈述倾向时，可加入 often、tend to 等词，避免把统计倾向说成没有例外的规律。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The second ramp was slightly steeper than the first, so the cart moved faster.</p></blockquote><p>第二个坡道比第一个略陡，因此小车移动得更快。</p><p>slightly 修饰 steeper，than the first 省略 ramp；faster 在此修饰 moved。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>very faster 应改为 much faster 或 a little faster；very fast 则是原级搭配。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>交替朗读 fast、faster 和 far、farther，回听时检查比较级尾音；在示范中重读 first test，提醒自己范围限制。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The blue plane travelled farther than the red one in our first test. Its wings were also wider. We need more trials before drawing a conclusion.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句比较两次纸飞机测试，说明条件与结果，不把单次结果说成定律。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>用 in our first test 限定范围，最后一句明确证据不足。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：This surface is ___ smoother.（much/very）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> much 可以修饰比较级。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句中 the first 省略了哪个名词？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> ramp</p><p><strong>解析：</strong> 比较双方都是坡道。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 fast 的比较级写出。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> faster</p><p><strong>解析：</strong> 单音节形容词或副词通常加 er。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：比较级与比较对象一致。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-008">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-010">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
